def get(name):
 p=R/'tables'/name;return pd.read_csv(p)if p.exists()else pd.DataFrame()
def table(d,cols):
 cols=list(dict.fromkeys([c for c in cols if c in d]+[c for c in ['status','n','stocks','events']if c in d]));f=d[cols].copy();f=f.rename(columns={'n':'Obs','stocks':'股票数','events':'事件段数'})
 if f.empty:return '（无可用结果；状态见对应CSV。）'
 for c in ['Obs','股票数','事件段数']:
  if c in f:f[c]=f[c].map(lambda v:'NA'if pd.isna(v)else f'{int(v):,}')
 return f.to_markdown(index=False,floatfmt='.6g')
def section(title,conclusion,d,cols,adverse):return f'## {title}\n\n结论：{conclusion}\n\n{table(d,cols)}\n\n最不利事实：{adverse}\n\n'

